informal_sketch.pseudocode:
class Task:
    def __init__(self, C, T, delta):
        self.C = C
        self.T = T
        self.D = T # Implicit deadline
        self.delta = delta
        self.u = C / T

def initialize_system(task_data):
    task_set = []
    for data in task_data:
        task_set.append(Task(data['C'], data['T'], data['delta']))

    # Sort tasks by period for fixed-priority assignment
    task_set.sort(key=lambda task: task.T)

    U_total = sum(task.u for task in task_set)

    # Determine hp_i for each task
    for i, task_i in enumerate(task_set):
        task_i.hp = [task_set[j] for j in range(i)]

    # Check for loose-harmonic property
    is_loose_harmonic = True
    if len(task_set) > 0:
        T_1 = task_set[0].T
        for task in task_set:
            if task.T % T_1 != 0:
                is_loose_harmonic = False
                break

    return task_set, U_total, is_loose_harmonic

def calculate_rbf_i(task_i, task_set, t):
    demand = task_i.C
    for task_j in task_i.hp:
        demand += math.ceil(t / task_j.T) * task_j.C
    return demand

def calculate_beta_i_background(task_i, task_set):
    max_blocking = 0
    # In practice, t is chosen from a finite set of critical instants
    # For simplicity, we iterate over a range, but real implementation uses specific points
    for t in range(task_i.C + 1, task_i.T + 1):
        rbf_val = calculate_rbf_i(task_i, task_set, t)
        current_blocking = t - rbf_val
        if current_blocking > max_blocking:
            max_blocking = current_blocking
    return max_blocking

def calculate_Q_i_background(task_set, beta_values):
    Q_values = [float('inf')] * len(task_set)
    Q_values[0] = float('inf') # Q_1 is infinity

    for i in range(1, len(task_set)):
        Q_values[i] = min(Q_values[i-1], beta_values[i])
    return Q_values

def define_S_i_periodic(task_i, task_set, beta_values, T_1, C_1):
    S_i = []
    for task_k in task_i.hp:
        if task_k.T != T_1: # Exclude tau_1
            # beta_k would be calculated using the RS-LP specific formula (Eq 9)
            # For now, assume beta_values contains these pre-calculated values
            if beta_values[task_k.index] < 2 * (T_1 - C_1):
                S_i.append(task_k)
    return S_i

def calculate_beta_i_rs_lp(task_i, task_set, delta_i_t_func):
    max_blocking = 0
    # Iterate over relevant time points
    for t in range(task_i.C + 1, task_i.T + 1):
        total_demand = 0
        for k in range(task_i.index + 1):
            total_demand += calculate_rbf_star_k(task_set[k], t)

        preemption_cost = delta_i_t_func(t) # Assumes delta_i_t_func is available

        # Assuming the '+' in the paper's formula is a typo and should be '-' for logical consistency
        current_blocking = t - (total_demand + preemption_cost)

        if current_blocking > max_blocking:
            max_blocking = current_blocking
    return max_blocking

def define_S_h_i_loose_harmonic(task_i, task_set, beta_h_values, T_1, C_1):
    S_h_i = []
    for task_k in task_i.hp:
        if task_k.T != T_1: # Exclude tau_1
            # beta_h_k would be calculated using the RS-LP specific formula (Eq 14)
            # For now, assume beta_h_values contains these pre-calculated values
            if beta_h_values[task_k.index] < (T_1 - C_1):
                S_h_i.append(task_k)
    return S_h_i

def calculate_beta_h_i_rs_lp(task_i, task_set, delta_h_i_t_func):
    max_blocking = 0
    # Iterate over relevant time points
    for t in range(task_i.C + 1, task_i.T + 1):
        total_demand = 0
        for k in range(task_i.index + 1):
            total_demand += calculate_rbf_star_k(task_set[k], t)

        preemption_cost = delta_h_i_t_func(t) # Assumes delta_h_i_t_func is available

        # Assuming the '+' in the paper's formula is a typo and should be '-' for logical consistency
        current_blocking = t - (total_demand + preemption_cost)

        if current_blocking > max_blocking:
            max_blocking = current_blocking
    return max_blocking

def calculate_P_C_i_j_lower_bound(C_i_j, T_1, C_1):
    max_segment_length = 2 * (T_1 - C_1)
    if max_segment_length <= 0: # Handle edge case where T_1 <= C_1
        return float('inf') # Cannot schedule

    num_segments = math.ceil(C_i_j / max_segment_length)
    return max(0, num_segments - 1)

def calculate_C_i_with_overhead(task_i, T_1, C_1, max_iterations=100, tolerance=0.001):
    C_i_prime_current = task_i.C
    for _ in range(max_iterations):
        P_val = calculate_P_C_i_j_lower_bound(C_i_prime_current, T_1, C_1)
        C_i_prime_next = task_i.C + P_val * task_i.delta
        if abs(C_i_prime_next - C_i_prime_current) < tolerance:
            return C_i_prime_next
        C_i_prime_current = C_i_prime_next
    return C_i_prime_current # Return last value if not converged (should converge for valid systems)

def get_max_execution_segment_length(T_1, C_1):
    # Based on Algorithm 1, Line 3: segment_length = a_next_1 + (T_1 - C_1) - t
    # Maximize when (a_next_1 - t) is maximized.
    # Max (a_next_1 - t) occurs when t is just after a_prev_1 + C_1, and a_next_1 is a_prev_1 + T_1.
    # So, a_next_1 - t approx T_1 - C_1
    return 2 * (T_1 - C_1)

def calculate_P_i_t(t, T_1, S_i):
    bound_1 = math.ceil(t / T_1)

    tau_1_preemptions = math.ceil(t / (2 * T_1))
    other_preemptions = 0
    for task_k in S_i:
        other_preemptions += math.ceil(t / task_k.T)
    bound_2 = tau_1_preemptions + other_preemptions

    return min(bound_1, bound_2)

def calculate_B_i(task_i, task_set, T_1, C_1, beta_values):
    if task_i.index == len(task_set) - 1: # If it's the lowest priority task
        return 0

    max_C_j_lower_priority = 0
    for j in range(task_i.index + 1, len(task_set)):
        max_C_j_lower_priority = max(max_C_j_lower_priority, task_set[j].C)

    if beta_values[task_i.index] < 2 * (T_1 - C_1):
        return min(T_1 - C_1, max_C_j_lower_priority)
    else:
        return min(2 * (T_1 - C_1), max_C_j_lower_priority)

def calculate_P_h_i_t(t, T_1, S_h_i):
    bound_1 = math.ceil(t / T_1)

    tau_1_preemptions = math.ceil(t / (2 * T_1))
    other_preemptions = 0
    for task_k in S_h_i:
        other_preemptions += math.ceil(t / task_k.T)
    bound_2 = tau_1_preemptions + other_preemptions

    return min(bound_1, bound_2)

formal_description.statement:
In a loose-harmonic task set, the maximum blocking time B_h_i suffered by any job released by tau_i due to lower priority tasks, is upper bounded by:
B_h_i = { 0 if i = n or beta_h_i < (T_1 - C_1) 
        { min(T_1 - C_1, max_{j=i+1 to n}(C_j)) otherwise }

informal_sketch.pseudocode:
def calculate_B_h_i(task_i, task_set, T_1, C_1, beta_h_values):
    if task_i.index == len(task_set) - 1 or beta_h_values[task_i.index] < (T_1 - C_1):
        return 0

    max_C_j_lower_priority = 0
    for j in range(task_i.index + 1, len(task_set)):
        max_C_j_lower_priority = max(max_C_j_lower_priority, task_set[j].C)

    return min(T_1 - C_1, max_C_j_lower_priority)

def calculate_WCRT_periodic(task_i, task_set, B_i_val, delta_i_t_func, max_iterations=100, tolerance=0.001):
    R_i_current = B_i_val + task_i.C
    for _ in range(max_iterations):
        interference = 0
        for task_j in task_i.hp:
            interference += math.ceil(R_i_current / task_j.T) * task_j.C

        preemption_cost = delta_i_t_func(R_i_current)

        R_i_next = B_i_val + task_i.C + interference + preemption_cost

        if abs(R_i_next - R_i_current) < tolerance:
            return R_i_next
        R_i_current = R_i_next
    return R_i_current # Return last value if not converged

def is_schedulable_periodic(task_set, B_values, delta_i_t_funcs):
    for i, task_i in enumerate(task_set):
        R_i = calculate_WCRT_periodic(task_i, task_set, B_values[i], delta_i_t_funcs[i])
        if R_i > task_i.D:
            return False # Task misses deadline
    return True # All tasks schedulable

def calculate_WCRT_loose_harmonic(task_i, task_set, B_h_i_val, delta_h_i_t_func, max_iterations=100, tolerance=0.001):
    R_h_i_current = B_h_i_val + task_i.C
    for _ in range(max_iterations):
        interference = 0
        for task_j in task_i.hp:
            interference += math.ceil(R_h_i_current / task_j.T) * task_j.C

        preemption_cost = delta_h_i_t_func(R_h_i_current)

        R_h_i_next = B_h_i_val + task_i.C + interference + preemption_cost

        if abs(R_h_i_next - R_h_i_current) < tolerance:
            return R_h_i_next
        R_h_i_current = R_h_i_next
    return R_h_i_current # Return last value if not converged

def is_schedulable_loose_harmonic(task_set, B_h_values, delta_h_i_t_funcs):
    for i, task_i in enumerate(task_set):
        R_h_i = calculate_WCRT_loose_harmonic(task_i, task_set, B_h_values[i], delta_h_i_t_funcs[i])
        if R_h_i > task_i.D:
            return False # Task misses deadline
    return True # All tasks schedulable

def calculate_P_lb_i(task_i, T_1, C_1):
    C_i_prime = calculate_C_i_with_overhead(task_i, T_1, C_1)
    return calculate_P_C_i_j_lower_bound(C_i_prime, T_1, C_1)

def check_necessary_feasibility(task_set, T_1, C_1):
    total_effective_utilization = 0
    for task_i in task_set:
        C_i_prime = calculate_C_i_with_overhead(task_i, T_1, C_1)
        total_effective_utilization += C_i_prime / task_i.T

    return total_effective_utilization <= 1
